<?php echo view('operations_approval\Views\partials\styles'); ?><div class="page-title clearfix"><h1><?php echo app_lang('operations_reports'); ?></h1><div class="title-button-group"><?php echo anchor(get_uri('operations/export'),'<i data-feather="download" class="icon-16"></i> '.app_lang('export'),['class'=>'btn btn-primary']); ?></div></div>
<div class="card"><div class="card-body"><form method="get"><div class="row"><div class="col"><input type="date" name="date_from" class="form-control" value="<?php echo esc($filters['date_from']); ?>"></div><div class="col"><input type="date" name="date_to" class="form-control" value="<?php echo esc($filters['date_to']); ?>"></div><div class="col"><select name="workflow_id" class="form-control"><option value=""><?php echo app_lang('operations_workflow'); ?></option><?php foreach($workflows as $w){ ?><option value="<?php echo $w->id; ?>" <?php echo $filters['workflow_id']==$w->id?'selected':''; ?>><?php echo esc($w->name); ?></option><?php } ?></select></div><div class="col"><select name="status" class="form-control"><option value=""><?php echo app_lang('status'); ?></option><?php foreach(['draft','pending_approval','returned','rejected','completed','cancelled','configuration_error'] as $s){ ?><option <?php echo $filters['status']===$s?'selected':''; ?>><?php echo $s; ?></option><?php } ?></select></div><div class="col-auto"><button class="btn btn-primary"><?php echo app_lang('filter'); ?></button></div></div></form></div></div>
<div class="row"><?php foreach(['status','workflow','monthly','turnaround'] as $report){ ?><div class="col-lg-6"><div class="card"><div class="card-header"><h4><?php echo app_lang('operations_report_'.$report); ?></h4></div><div class="table-responsive"><table class="table"><thead><tr><th><?php echo app_lang('name'); ?></th><th><?php echo app_lang('total'); ?></th></tr></thead><tbody><?php foreach($summary[$report] as $row){ ?><tr><td><?php echo esc(ucwords(str_replace('_',' ',$row['label']))); ?></td><td><?php echo esc($row['total']); ?></td></tr><?php } ?></tbody></table></div></div></div><?php } ?></div>
